def transform(grid):
    h, w = len(grid), len(grid[0])
    outside = set()
    stack = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and (r in (0, h - 1) or c in (0, w - 1)):
                outside.add((r, c))
                stack.append((r, c))

    while stack:
        r, c = stack.pop()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                    and (nr, nc) not in outside):
                outside.add((nr, nc))
                stack.append((nr, nc))

    out = [row[:] for row in grid]
    unseen = {(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == 0 and (r, c) not in outside}

    colors = {(3, 3): 8, (5, 5): 4, (7, 7): 3}
    while unseen:
        start = unseen.pop()
        component = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                if (nr, nc) in unseen:
                    unseen.remove((nr, nc))
                    component.add((nr, nc))
                    stack.append((nr, nc))

        rows = [r for r, c in component]
        cols = [c for r, c in component]
        size = (max(rows) - min(rows) + 1, max(cols) - min(cols) + 1)
        color = colors.get(size, colors.get(size[::-1], 8))
        for r, c in component:
            out[r][c] = color

    return out
